/* Count the number of cartesian points in each quadrant. The vector points contains a list of `Point` objects.
   Store the counts in `bins`.
   Use OpenMP to count in parallel.
   Example:

   input: [{x=1.5, y=0.1}, {x=-3, y=1.1}, {x=5, y=9}, {x=1.5, y=-1}, {x=3, y=-7}, {x=0.1, y=2}]
   output: [3, 1, 0, 2]
*/
void countQuadrants(std::vector<Point> const& points, std::array<size_t, 4> &bins) {

```cpp
#include <array>
#include <cstddef>
#include <vector>
#include <omp.h>

void countQuadrants(std::vector<Point> const& points, std::array<size_t, 4> &bins) {
    size_t q1 = 0;
    size_t q2 = 0;
    size_t q3 = 0;
    size_t q4 = 0;

    const long long n = static_cast<long long>(points.size());

    #pragma omp parallel for default(none) shared(points, n) reduction(+:q1, q2, q3, q4)
    for (long long i = 0; i < n; ++i) {
        const Point& p = points[static_cast<std::size_t>(i)];

        if (p.x > 0.0 && p.y > 0.0) {
            ++q1; // Quadrant I
        } else if (p.x < 0.0 && p.y > 0.0) {
            ++q2; // Quadrant II
        } else if (p.x < 0.0 && p.y < 0.0) {
            ++q3; // Quadrant III
        } else if (p.x > 0.0 && p.y < 0.0) {
            ++q4; // Quadrant IV
        }
        // Points lying on an axis are not counted in any quadrant.
    }

    bins = {q1, q2, q3, q4};
}
